ruleContent.content:
@js:
// 1. 取 aid：优先从当前章节 URL（slide 页）拿，兜底从详情页 URL 拿
var aid = (String(baseUrl).match(/aid-(\d+)/) || [])[1]
       || (String(baseUrl).match(/id-(\d+)/)  || [])[1];

if (!aid) { java.log('未取到 aid: ' + baseUrl); }

// 2. 拉取数据 JS 文件（mReader.initData 所在文件）
var host = 'https://www.wnacg.ru';
var jsUrl = host + '/photos-item-aid-' + aid + '.html';
var raw = String(java.ajax(jsUrl) || '');

// 3. 截出 page_url 数组段，再逐个抽出图片地址
var imgs = [];
var seg = raw.match(/["']page_url["']\s*:\s*\[([\s\S]*?)\]/);
if (seg) {
    var re = /["']([^"']+?\.(?:jpg|jpeg|png|webp|gif|bmp))["']/gi, m;
    while ((m = re.exec(seg[1])) !== null) {
        var u = m[1].replace(/\\\//g, '/');
        if (/^\/\//.test(u)) u = 'https:' + u;
        u = u.replace(/^http:\/\//i, 'https://');
        imgs.push(u);
    }
}

if (imgs.length === 0) { java.log('page_url 解析为空, aid=' + aid); }

// 4. 输出 img；单引号 JSON 选项清掉 Referer 防盗链（双引号会截断 src 属性）
var opt = ",{'headers':{'Referer':''}}";
imgs.map(function (x) { return '<img src="' + x + opt + '">'; }).join('\n')

