else cls = String(result || '');
var m = cls.match(/cate-(\d+)/) || String(baseUrl || '').match(/cate-(\d+)/);
var map = {'1':'同人志/汉化','12':'同人志/日语','16':'同人志/英语','5':'同人志','2':'CG','3':'Cosplay','22':'3D','37':'AI','9':'单行本/汉化','13':'单行本/日语','17':'单行本/英语','6':'单行本','10':'杂志&短篇/汉化','14':'杂志&短篇/日语','18':'杂志&短篇/English','7':'杂志&短篇','20':'韩漫/汉化','21':'韩漫/生肉','19':'韩漫'};
var out = (m && map[m[1]]) ? map[m[1]] : '';
if (!out) {
  var t = '';
  try { t = String(java.getString("//div[@class='title']/a/@title") || java.getString("//div[@class='title']/a/text()") || ''); } catch(e) {}
  if (/(繁體|繁体|繁中)/.test(t)) out = '繁体中文';
  else if (/(漢|汉|翻訳|翻译|翻譯|中国語|中國語|中文|嵌字|个人|個人|渣翻|机翻|機翻)/.test(t)) out = '汉化';
  else if (/(無修正|无修正)/.test(t)) out = '日语';
  else if (/(English|英訳|英语|英語)/i.test(t)) out = '英语';
  else if (t) out = '日语';
}
out;

